import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { Plus, Users, MapPin, Calendar, Circle, Target, Search, Filter, X, Share2 } from 'lucide-react';
import { getApiBaseUrl } from '../utils/api';
import LocationAutocomplete from './LocationAutocomplete';

interface Game {
  id: string;
  title: string;
  sport: string;
  location: string;
  max_players: number;
  current_players: number;
  creator_name: string;
  created_at: string;
  game_time?: string;
  level?: string;
  is_casual?: number;
  is_private?: boolean;
  min_age?: number;
  is_money_game?: boolean;
  entry_fee?: number;
  total_pot?: number;
}

const sportIcons: { [key: string]: React.ComponentType<any> } = {
  baseball: Circle,
  basketball: Circle,
  soccer: Target,
  softball: Circle,
};

const sportColors: { [key: string]: string } = {
  baseball: 'bg-blue-500',
  basketball: 'bg-orange-500',
  soccer: 'bg-green-500',
  softball: 'bg-pink-500',
};

const availableSports = [
  'baseball', 'basketball', 'soccer', 'softball'
];

const Dashboard: React.FC = () => {
  const [games, setGames] = useState<Game[]>([]);
  const [filteredGames, setFilteredGames] = useState<Game[]>([]);
  const [joinedGames, setJoinedGames] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filters, setFilters] = useState({
    sport: '',
    searchTerm: '',
    level: '',
    showCasual: false
  });
  const [searchLocation, setSearchLocation] = useState('');
  const [searchLocationData, setSearchLocationData] = useState<any>(null);
  const [searchRadius, setSearchRadius] = useState(6); // Default 6 miles radius
  const [showFilters, setShowFilters] = useState(false);
  const [nearbyGames, setNearbyGames] = useState<Game[]>([]);
  const { user } = useAuth();

  const fetchGames = useCallback(async () => {
    try {
      const apiBaseUrl = getApiBaseUrl();

      // Build query parameters for location search
      const params = new URLSearchParams();
      if (searchLocationData?.lat && searchLocationData?.lng && searchRadius) {
        params.append('lat', searchLocationData.lat.toString());
        params.append('lng', searchLocationData.lng.toString());
        // Convert miles to kilometers for backend (1 mile = 1.609344 km)
        params.append('radius', (searchRadius * 1.609344).toString());
      }

      const response = await fetch(`${apiBaseUrl}/api/games?${params.toString()}`);
      if (response.ok) {
        const data = await response.json();
        setGames(data);
        setFilteredGames(data);
        // Fetch joined games after games are loaded
        if (user) {
          fetchJoinedGames(data);
        }
      }
    } catch (error) {
      console.error('Error fetching games:', error);
      setError('Failed to load games');
    } finally {
      setLoading(false);
    }
  }, [user, searchLocationData, searchRadius]); // eslint-disable-line react-hooks/exhaustive-deps

  // Filter games based on current filters
  const applyFilters = useCallback(() => {
    let filtered = games;

    // Filter by sport
    if (filters.sport) {
      filtered = filtered.filter(game => 
        game.sport.toLowerCase() === filters.sport.toLowerCase()
      );
    }

    // Filter by search term (title or creator)
    if (filters.searchTerm) {
      filtered = filtered.filter(game => 
        game.title.toLowerCase().includes(filters.searchTerm.toLowerCase()) ||
        game.creator_name.toLowerCase().includes(filters.searchTerm.toLowerCase())
      );
    }

    if (filters.level) {
      filtered = filtered.filter(game => game.level === filters.level);
    }
    if (filters.showCasual) {
      filtered = filtered.filter(game => game.is_casual);
    }

    setFilteredGames(filtered);
  }, [games, filters]);

  // Apply filters whenever filters or games change
  useEffect(() => {
    applyFilters();
  }, [applyFilters]);

  const clearFilters = () => {
    setFilters({
      sport: '',
      searchTerm: '',
      level: '',
      showCasual: false
    });
  };

  const getShareLink = (gameId: string) => {
    return `${window.location.origin}/game/${gameId}`;
  };

  const copyToClipboard = async (gameId: string) => {
    try {
      await navigator.clipboard.writeText(getShareLink(gameId));
      setLinkCopied(true);
      setTimeout(() => setLinkCopied(false), 2000);
    } catch (err) {
      // Fallback for older browsers
      const textArea = document.createElement('textarea');
      textArea.value = getShareLink(gameId);
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
      setLinkCopied(true);
      setTimeout(() => setLinkCopied(false), 2000);
    }
  };

  const shareGame = async (game: Game) => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: game.title,
          text: `Join me for a game of ${game.sport} at ${game.location}!`,
          url: getShareLink(game.id),
        });
      } catch (err) {
        // User cancelled sharing or error occurred
        console.log('Error sharing:', err);
      }
    } else {
      // Fallback to copy to clipboard
      copyToClipboard(game.id);
    }
  };

  const hasActiveFilters = filters.sport || filters.searchTerm || filters.level || filters.showCasual;

  const fetchJoinedGames = useCallback(async (gamesList: Game[]) => {
    if (!user || gamesList.length === 0) return;

    try {
      const apiBaseUrl = getApiBaseUrl();
      const joinedSet = new Set<string>();

      console.log('Checking join status for', gamesList.length, 'games');

      // Check each game to see if user has joined
      for (const game of gamesList) {
        const response = await fetch(`${apiBaseUrl}/api/games/${game.id}/joined`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });

        if (response.ok) {
          const { joined } = await response.json();
          console.log(`Game ${game.title}: joined = ${joined}`);
          if (joined) {
            joinedSet.add(game.id);
          }
        } else {
          console.log(`Failed to check join status for game ${game.title}:`, response.status);
        }
      }

      console.log('Joined games:', Array.from(joinedSet));
      setJoinedGames(joinedSet);
    } catch (error) {
      console.error('Error fetching joined games:', error);
    }
  }, [user]);

  const joinGame = useCallback(async (gameId: string) => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/join`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        setJoinedGames(prev => new Set(Array.from(prev).concat(gameId)));
        fetchGames(); // Refresh the games list
      } else {
        const error = await response.json();
        alert(error.error || 'Failed to join game');
      }
    } catch (error) {
      console.error('Error joining game:', error);
      alert('Failed to join game');
    }
  }, [fetchGames]);

  const leaveGame = useCallback(async (gameId: string) => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/leave`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        setJoinedGames(prev => {
          const newSet = new Set(prev);
          newSet.delete(gameId);
          return newSet;
        });
        fetchGames(); // Refresh the games list
      } else {
        const error = await response.json();
        alert(error.error || 'Failed to leave game');
      }
    } catch (error) {
      console.error('Error leaving game:', error);
      alert('Failed to leave game');
    }
  }, [fetchGames]);

  const cancelGame = async (gameId: string) => {
    if (!window.confirm('Are you sure you want to cancel this game? This cannot be undone.')) return;
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/games/${gameId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      if (response.ok) {
        fetchGames();
      } else {
        const error = await response.json();
        alert(error.error || 'Failed to cancel game');
      }
    } catch (error) {
      alert('Failed to cancel game');
    }
  };

  useEffect(() => {
    fetchGames();
  }, [fetchGames]);

  // Get user's location and fetch nearby games on mount
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          fetchNearbyGames(latitude, longitude);
        },
        (error) => {
          console.log('Location access denied or unavailable:', error);
          // Silently fail - don't show error to user
        }
      );
    }
  }, []);

  const fetchNearbyGames = async (lat: number, lng: number) => {
    setNearbyGamesLoading(true);
    try {
      const apiBaseUrl = getApiBaseUrl();
      // Use minimum radius of 3 miles, convert to km
      const radiusInKm = 3 * 1.609344;
      const params = new URLSearchParams();
      params.append('lat', lat.toString());
      params.append('lng', lng.toString());
      params.append('radius', radiusInKm.toString());

      const response = await fetch(`${apiBaseUrl}/api/games?${params.toString()}`);
      if (response.ok) {
        const data = await response.json();
        // Limit to 5 games
        setNearbyGames(data.slice(0, 5));
      }
    } catch (error) {
      console.error('Error fetching nearby games:', error);
    } finally {
      setNearbyGamesLoading(false);
    }
  };

  // Helper function to extract city from location string
  const extractCity = (location: string): string => {
    if (!location) return 'Unknown';
    // Location format is usually like "City, State, Country" or "Address, City, State"
    const parts = location.split(',').map(s => s.trim());
    if (parts.length === 0) return location;

    // If we have multiple parts, try to extract city
    // Common formats:
    // - "Street Address, City, State, Country" -> City is usually second to last
    // - "City, State, Country" -> City is first
    // - "City, State" -> City is first
    if (parts.length >= 2) {
      // For addresses with street, city is typically the second-to-last part before state
      // For simple "City, State" format, city is the first part
      if (parts.length >= 3) {
        // Likely has street address, so city is second to last
        return parts[parts.length - 2];
      } else {
        // Simple format, city is first
        return parts[0];
      }
    }
    return parts[0] || location;
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto">
      <div className="mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Welcome back, {user?.username}! 🏀</h1>
            <p className="mt-2 text-gray-600">Find and join pickup games in your area</p>
          </div>
          <Link
            to="/create-game"
            className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create Game
          </Link>
        </div>
      </div>

      {error && (
        <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md">
          {error}
        </div>
      )}

      {/* Nearby Games Section */}
      {nearbyGames.length > 0 && (
        <div className="mb-8 bg-white bg-opacity-90 backdrop-blur-md rounded-lg shadow-xl p-6">
          <h2 className="text-xl font-semibold text-gray-900 flex items-center mb-4">
            <MapPin className="w-5 h-5 mr-2" />
            Games Near You (within 3 miles)
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
            {nearbyGames.map((game) => {
              const SportIcon = sportIcons[game.sport.toLowerCase()] || Circle;
              const sportColor = sportColors[game.sport.toLowerCase()] || 'bg-gray-500';

              return (
                <Link
                  key={game.id}
                  to={`/game/${game.id}`}
                  className="bg-gray-50 rounded-lg p-4 hover:bg-gray-100 transition-colors border border-gray-200"
                >
                  <div className="flex items-center justify-between mb-2">
                    <div className={`w-8 h-8 ${sportColor} rounded-lg flex items-center justify-center`}>
                      <SportIcon className="w-4 h-4 text-white" />
                    </div>
                    <span className="text-xs font-medium text-gray-500 capitalize">{game.sport}</span>
                  </div>
                  <h3 className="text-sm font-semibold text-gray-900 mb-2 line-clamp-2">{game.title}</h3>
                  <p className="text-xs text-gray-600 mb-2">{extractCity(game.location)}</p>
                  <div className="flex items-center text-xs text-gray-600">
                    <Users className="w-3 h-3 mr-1" />
                    <span>{game.current_players}/{game.max_players} players</span>
                  </div>
                </Link>
              );
            })}
          </div>
        </div>
      )}

      {/* Find Game Section */}
      <div className="mb-8 bg-white bg-opacity-90 backdrop-blur-md rounded-lg shadow-xl p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold text-gray-900 flex items-center">
            <Search className="w-5 h-5 mr-2" />
            Find Game
          </h2>
          <button
            onClick={() => setShowFilters(!showFilters)}
            className="inline-flex items-center px-3 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50"
          >
            <Filter className="w-4 h-4 mr-2" />
            {showFilters ? 'Hide Filters' : 'Show Filters'}
          </button>
        </div>

        {/* Search Bar */}
        <div className="mb-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input
              type="text"
              placeholder="Search games by player"
              value={filters.searchTerm}
              onChange={(e) => setFilters(prev => ({ ...prev, searchTerm: e.target.value }))}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            />
          </div>
        </div>

        {/* Location Search */}
        <div className="mb-4 p-4 bg-gray-50 rounded-lg">
          <h3 className="text-sm font-medium text-gray-700 mb-3">Search by Location</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Location</label>
              <LocationAutocomplete
                value={searchLocation}
                onChange={(newLocation, data) => {
                  setSearchLocation(newLocation);
                  setSearchLocationData(data);
                }}
                placeholder="Search for a location..."
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Radius (miles)</label>
              <select
                value={searchRadius}
                onChange={(e) => setSearchRadius(Number(e.target.value))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value={3}>3 miles</option>
                <option value={6}>6 miles</option>
                <option value={15}>15 miles</option>
                <option value={30}>30 miles</option>
                <option value={60}>60 miles</option>
              </select>
            </div>
          </div>
          {(searchLocation || searchLocationData) && (
            <div className="mt-3 flex items-center justify-between">
              <div className="text-sm text-gray-600">
                {searchLocation && (
                  <span>Searching near: <strong>{searchLocation}</strong></span>
                )}
              </div>
              <button
                onClick={() => {
                  setSearchLocation('');
                  setSearchLocationData(null);
                }}
                className="text-sm text-red-600 hover:text-red-800"
              >
                Clear Location
              </button>
            </div>
          )}
        </div>

        {/* Filters */}
        {showFilters && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Sport</label>
              <select
                value={filters.sport}
                onChange={(e) => setFilters(prev => ({ ...prev, sport: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">All Sports</option>
                {availableSports.map(sport => (
                  <option key={sport} value={sport}>
                    {sport.charAt(0).toUpperCase() + sport.slice(1)}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Skill Level</label>
              <select
                value={filters.level}
                onChange={e => setFilters(prev => ({ ...prev, level: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">All Levels</option>
                <option value="A">A (Advanced)</option>
                <option value="B">B (Intermediate)</option>
                <option value="C">C (Recreational)</option>
              </select>
            </div>
            <div className="flex items-center mt-6">
              <input
                id="showCasual"
                type="checkbox"
                checked={filters.showCasual}
                onChange={e => setFilters(prev => ({ ...prev, showCasual: e.target.checked }))}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="showCasual" className="ml-2 block text-sm text-gray-700">
                Show only Casual Games
              </label>
            </div>
          </div>
        )}

        {/* Active Filters */}
        {hasActiveFilters && (
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <span className="text-sm text-gray-600">Active filters:</span>
              {filters.sport && (
                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                  Sport: {filters.sport}
                  <button
                    onClick={() => setFilters(prev => ({ ...prev, sport: '' }))}
                    className="ml-1 text-blue-600 hover:text-blue-800"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              )}
              {filters.searchTerm && (
                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-purple-100 text-purple-800">
                  Search: {filters.searchTerm}
                  <button
                    onClick={() => setFilters(prev => ({ ...prev, searchTerm: '' }))}
                    className="ml-1 text-purple-600 hover:text-purple-800"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              )}
              {filters.level && (
                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-indigo-100 text-indigo-800">
                  Level: {filters.level}
                  <button
                    onClick={() => setFilters(prev => ({ ...prev, level: '' }))}
                    className="ml-1 text-indigo-600 hover:text-indigo-800"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              )}
              {filters.showCasual && (
                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800">
                  Casual Only
                  <button
                    onClick={() => setFilters(prev => ({ ...prev, showCasual: false }))}
                    className="ml-1 text-yellow-600 hover:text-yellow-800"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </span>
              )}
            </div>
            <button
              onClick={clearFilters}
              className="text-sm text-gray-600 hover:text-gray-800 underline"
            >
              Clear all filters
            </button>
          </div>
        )}
      </div>

      {filteredGames.length === 0 ? (
        <div className="text-center py-12">
          <div className="mx-auto h-24 w-24 bg-gray-100 rounded-full flex items-center justify-center mb-4">
            <Search className="h-12 w-12 text-gray-400" />
          </div>
          <h3 className="text-lg font-medium text-gray-900 mb-2">
            {hasActiveFilters ? 'No games match your filters' : 'No games available'}
          </h3>
          <p className="text-gray-600 mb-6">
            {hasActiveFilters 
              ? 'Try adjusting your search criteria or clear filters to see all games.'
              : 'Be the first to create a pickup game!'
            }
          </p>
          {hasActiveFilters ? (
            <button
              onClick={clearFilters}
              className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700"
            >
              <X className="w-4 h-4 mr-2" />
              Clear Filters
            </button>
          ) : (
            <Link
              to="/create-game"
              className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700"
            >
              <Plus className="w-4 h-4 mr-2" />
              Create First Game
            </Link>
          )}
        </div>
              ) : (
          <>
            <div className="mb-4">
              <div className="flex items-center justify-between">
                <h3 className="text-lg font-medium text-gray-900">
                  {hasActiveFilters 
                    ? `Found ${filteredGames.length} game${filteredGames.length !== 1 ? 's' : ''}`
                    : `All Games (${filteredGames.length})`
                  }
                </h3>
                {hasActiveFilters && (
                  <span className="text-sm text-gray-600">
                    Showing {filteredGames.length} of {games.length} total games
                  </span>
                )}
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredGames.map((game) => {
                const SportIcon = sportIcons[game.sport.toLowerCase()] || Circle;
                const sportColor = sportColors[game.sport.toLowerCase()] || 'bg-gray-500';

                return (
                  <div key={game.id} className="bg-white bg-opacity-90 backdrop-blur-md rounded-lg shadow-xl hover:shadow-2xl transition-all duration-300 border border-white border-opacity-20 flex flex-col h-full">
                    <div className="p-6 flex-1 flex flex-col">
                      <div className="flex items-center justify-between mb-4">
                        <div className={`w-10 h-10 ${sportColor} rounded-lg flex items-center justify-center`}>
                          <SportIcon className="w-6 h-6 text-white" />
                        </div>
                        <span className="text-sm font-medium text-gray-500 capitalize">{game.sport}</span>
                      </div>

                      <h3 className="text-lg font-semibold text-gray-900 mb-3 line-clamp-2">{game.title}</h3>

                      <div className="flex items-center space-x-2 mb-2">
                        <span className="inline-block px-2 py-1 rounded text-xs font-semibold bg-gray-200 text-gray-700">Level: {game.level}</span>
                        {game.is_casual ? (
                          <span className="inline-block px-2 py-1 rounded text-xs font-semibold bg-yellow-100 text-yellow-800">Casual</span>
                        ) : null}
                        {game.min_age && game.min_age > 0 ? (
                          <span className="inline-block px-2 py-1 rounded text-xs font-semibold bg-purple-100 text-purple-800">18+</span>
                        ) : null}
                        {game.is_money_game ? (
                          <span className="inline-block px-2 py-1 rounded text-xs font-semibold bg-green-100 text-green-800">💰 ${game.entry_fee}</span>
                        ) : null}
                      </div>

                      <div className="space-y-2 mb-6 flex-1">
                        <div className="flex items-center text-sm text-gray-600">
                          <MapPin className="w-4 h-4 mr-2 flex-shrink-0" />
                          <span className="truncate">{game.location}</span>
                        </div>
                        <div className="flex items-center text-sm text-gray-600">
                          <Users className="w-4 h-4 mr-2 flex-shrink-0" />
                          {game.current_players}/{game.max_players} players
                        </div>
                        <div className="flex items-center text-sm text-gray-600">
                          <Calendar className="w-4 h-4 mr-2 flex-shrink-0" />
                          {game.game_time ? formatDate(game.game_time) : 'No time set'}
                        </div>
                      </div>

                      <div className="mt-auto">
                        <div className="flex flex-col space-y-3">
                          <div className="flex items-center justify-between">
                            <span className="text-sm text-gray-500 truncate mr-2">by {game.creator_name}</span>
                          </div>
                          <div className="flex flex-col sm:flex-row gap-2">
                            <Link
                              to={`/game/${game.id}`}
                              className="flex-1 inline-flex items-center justify-center px-3 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-all duration-200"
                            >
                              View Lobby
                            </Link>
                            <button
                              onClick={() => shareGame(game)}
                              className="inline-flex items-center justify-center px-3 py-2 border border-blue-300 text-sm font-medium rounded-md text-blue-700 bg-white hover:bg-blue-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-all duration-200"
                              title="Share game"
                            >
                              <Share2 className="w-4 h-4" />
                            </button>
                            <button
                              onClick={() => {
                                console.log('Button clicked for game:', game.title, 'joined:', joinedGames.has(game.id));
                                joinedGames.has(game.id) ? leaveGame(game.id) : joinGame(game.id);
                              }}
                              disabled={game.current_players >= game.max_players && !joinedGames.has(game.id)}
                              className={`flex-1 inline-flex items-center justify-center px-3 py-2 border text-sm font-medium rounded-md transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 ${
                                joinedGames.has(game.id)
                                  ? 'border-green-300 text-green-700 bg-green-50 hover:bg-green-100 focus:ring-green-500'
                                  : game.current_players >= game.max_players
                                  ? 'border-gray-300 text-gray-500 bg-gray-100 cursor-not-allowed'
                                  : 'border-transparent text-white bg-blue-600 hover:bg-blue-700 focus:ring-blue-500'
                              }`}
                            >
                              {joinedGames.has(game.id) 
                                ? 'Joined' 
                                : game.current_players >= game.max_players 
                                ? 'Full' 
                                : 'Join'
                              }
                            </button>
                            {user && user.username === game.creator_name && (
                              <button
                                onClick={() => cancelGame(game.id)}
                                className="flex-1 inline-flex items-center justify-center px-3 py-2 border border-red-300 text-sm font-medium rounded-md text-red-700 bg-white hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 transition-all duration-200"
                              >
                                Cancel Game
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        )}
      </div>
    );
  };

  export default Dashboard;
